def color_func(Y, mode='polygon'):
    # 紅色代表高電位(Voltage)，藍色代表恢復期(Recovery)
    if mode == 'polygon':
        norm = (Y[:,0] - Y[:,0].min()) / (np.ptp(Y[:,0]) + 1e-8)
        return plt.cm.OrRd(norm)
    elif mode == 'center':
        norm = (Y[:,1] - Y[:,1].min()) / (np.ptp(Y[:,1]) + 1e-8)
        return plt.cm.Blues(norm)
    else:
        return None
